-- Полное равенство исходному реестру: исходные GP batch_id, load_dts, record_source, payload и документ сохранены.
SELECT count(*) AS n FROM ((SELECT event_id,event_type,entity_id,entity_version,op,event_time,load_dts,record_source,batch_id,payload,event_document FROM {{source:oil_dds__event}} EXCEPT ALL SELECT event_id,event_type,entity_id,entity_version,op,event_time,load_dts,record_source,batch_id,payload,event_document FROM {{target:oil_dds__event}}) UNION ALL (SELECT event_id,event_type,entity_id,entity_version,op,event_time,load_dts,record_source,batch_id,payload,event_document FROM {{target:oil_dds__event}} EXCEPT ALL SELECT event_id,event_type,entity_id,entity_version,op,event_time,load_dts,record_source,batch_id,payload,event_document FROM {{source:oil_dds__event}})) q;
